patches.new:
// §54 cross-page A destination fixture (test-only, natural actual-DMA run).
// +a-dst-offset=0|3072|4088 (default 0): effective A-side destination offset
// in the shared-source natural 2 KiB geometry.  BOTH nonzero values make the
// 2048-byte A copy span two A destination pages:
//   3072 -> FIRST A page carries 1024 B (128 beats) at PA 0x9010_0c00,
//           second A page carries the other 1024 B at PA 0x9010_1000;
//   4088 -> FIRST A page carries only 8 B (one beat) at PA 0x9010_0ff8,
//           second A page carries the remaining 2040 B (255 beats).
// Both offsets derive the SAME actual A destination next-page leaf PTE
// address 0x70048 (A L0 leaf index 9) from the last copied IOVA byte; no PTE
// table or payload constant is changed by this flag.  The terminal geometry
// fields first_a_page_beats / a_first_raw_parent_bytes_expected are DERIVED
// from this offset and carry the `expected` label: this DUT exposes no raw
// A-side parent-AW telemetry, so no observed raw-AW split is claimed.
// The ordinary (non-shared) path keeps its existing A destination offset
// NAT_DST_OFF (3072) and is unchanged.
// +a-next-pte-delay=N (default 0): bounded delay inserted BEFORE the first DDR
// RVALID of the ONE read that covers the actual A destination next-page leaf
// PTE address; it delays no other A context/source traffic.  Accepted for
// either nonzero cross-page offset (3072|4088) and applied at most once.
// Both flags are inert unless given.
static uint32_t a_dst_offset_opt = 0;   // +a-dst-offset (0|3072|4088)
static uint32_t a_next_pte_delay = 0;   // +a-next-pte-delay (0..100000)

