// §54 terminal A destination WRITE geometry: DERIVED, never observed.
// Cross-page shared fixture (offset 3072|4088) -> the FIRST A destination
// page carries (PAGE_BYTES - nat_a_dst_off)/8 of the 256 destination beats;
// every other combination reports the full 2048 B copy as 256 first-page
// beats.  `a_first_raw_parent_bytes_expected` keeps the `_expected` label
// because no raw A-side parent-AW split telemetry exists in this DUT.
uint32_t a_first_page_beats() const {
    if (shared_source && nat_a_dst_off != 0)
        return (uint32_t)((PAGE_BYTES - nat_a_dst_off) / 8u);
    return 256u;
}
uint32_t a_first_raw_parent_bytes_expected() const {
    return a_first_page_beats() * 8u;
}

